const canvas=document.getElementById('f'),ctx=canvas.getContext('2d');function rs(){canvas.width=innerWidth;canvas.height=innerHeight}rs();addEventListener('resize',rs);let pts=[];for(let i=0;i<60;i++)pts.push({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-0.5)*0.5,vy:(Math.random()-0.5)*0.5,r:Math.random()*1.5+0.5});function anim(){ctx.clearRect(0,0,canvas.width,canvas.height);pts.forEach((a,i)=>{a.x+=a.vx;a.y+=a.vy;if(a.x<0||a.x>canvas.width)a.vx*=-1;if(a.y<0||a.y>canvas.height)a.vy*=-1;ctx.beginPath();ctx.arc(a.x,a.y,a.r,0,6.28);ctx.fillStyle='rgba(255,255,255,0.5)';ctx.fill();pts.slice(i+1).forEach(b=>{let d=Math.hypot(a.x-b.x,a.y-b.y);if(d<100){ctx.strokeStyle='rgba(255,255,255,'+(0.07*(1-d/100))+')';ctx.lineWidth=0.5;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}})});requestAnimationFrame(anim)}anim();
